sure = {"IP1": 4, "IP2": 6, "IP3": 8, "IP4": 5, "IP5": 4, "IP6": 6}
onc = {"IP1": [], "IP2": ["IP1"], "IP3": ["IP2"], "IP4": ["IP1"],
       "IP5": ["IP3", "IP4"], "IP6": ["IP5"]}
sira = ["IP1", "IP2", "IP3", "IP4", "IP5", "IP6"]
EB, EBit = {}, {}
for n in sira:
    EB[n] = max([EBit[p] for p in onc[n]], default=0)
    EBit[n] = EB[n] + sure[n]
T = max(EBit.values())
ard = {n: [m for m in sira if n in onc[m]] for n in sira}
GBit, GB = {}, {}
for n in reversed(sira):
    GBit[n] = min([GB[s] for s in ard[n]], default=T)
    GB[n] = GBit[n] - sure[n]
for n in sira:
    print(n, EB[n], EBit[n], GB[n], GBit[n], GB[n] - EB[n])
print("SURE", T)
print("KRITIK", ",".join(n for n in sira if GB[n] == EB[n]))
